import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_activation_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void fused_leaky_multiply_leaky_kernel(
    const float* input,
    const float* multiplier,
    float* output,
    int num_elements,
    int channels,
    int depth,
    int height,
    int width) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < num_elements) {
        int remaining = idx;
        int w = remaining % width;
        remaining /= width;
        int h = remaining % height;
        remaining /= height;
        int d = remaining % depth;
        remaining /= depth;
        int c = remaining % channels;

        float x = input[idx];
        float a = fmaxf(x, 0.2f * x);
        a *= multiplier[c];
        a = fmaxf(a, 0.2f * a);
        output[idx] = a;
    }
}

torch::Tensor fused_leaky_multiply_leaky_cuda(torch::Tensor input, torch::Tensor multiplier) {
    TORCH_CHECK(input.device().is_cuda(), "input must be CUDA tensor");
    TORCH_CHECK(multiplier.device().is_cuda(), "multiplier must be CUDA tensor");
    TORCH_CHECK(input.dim() == 5, "input must be 5D tensor");
    TORCH_CHECK(multiplier.dim() == 4, "multiplier must be 4D tensor");

    auto output = torch::empty_like(input);
    int num_elements = input.numel();

    const int block_size = 256;
    dim3 grid((num_elements + block_size - 1) / block_size);

    fused_leaky_multiply_leaky_kernel<<<grid, block_size>>>(
        input.data_ptr<float>(),
        multiplier.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        input.size(1),
        input.size(2),
        input.size(3),
        input.size(4)
    );

    return output;
}
"""

fused_activation_cpp_source = "torch::Tensor fused_leaky_multiply_leaky_cuda(torch::Tensor input, torch::Tensor multiplier);"

fused_activation = load_inline(
    name='fused_activation',
    cpp_sources=fused_activation_cpp_source,
    cuda_sources=fused_activation_source,
    functions=['fused_leaky_multiply_leaky_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, multiplier_shape):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size, 
            stride=stride, padding=padding, 
            output_padding=output_padding
        )
        self.multiplier = nn.Parameter(torch.randn(multiplier_shape))
        self.max_pool = nn.MaxPool3d(kernel_size=2)
        self.fused_activation = fused_activation

    def forward(self, x):
        x = self.conv_transpose(x)
        x = self.fused_activation.fused_leaky_multiply_leaky_cuda(x, self.multiplier)
        x = self.max_pool(x)
        return x
